  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C97", "C107", "C112", "C116", "C144"],
  "claims": [
    {
      "claim": "L4 coumarin-scaffold records show well-absorbed status: decursin and related coumarin esters were assigned to the well-absorbed group in Caco-2 bidirectional permeability assays.",
      "card_ids": ["C97", "C104", "C109", "C135"]
    },
    {
      "claim": "Coumarin-type oral anticoagulants ethylbiscoumacetate and tromexan are described as well absorbed in humans, indicating a high fraction of the oral dose reaches systemic circulation.",
      "card_ids": ["C107", "C116"]
    },
    {
      "claim": "Warfarin, a 4-hydroxycoumarin, has human fraction absorbed of 94-100% across multiple records, supporting high intestinal absorption for the coumarin scaffold.",
      "card_ids": ["C98", "C103", "C129", "C130", "C131", "C144", "C145"]
    },
    {
      "claim": "Flavone, a closely related chromenone, showed high Caco-2 permeability (Papp B to A of 36 x 10^-6 cm/s), supporting high permeability of the bicyclic lactone core.",
      "card_ids": ["C112"]
    },
    {
      "claim": "No L4 record provides affirmative threshold-relevant evidence of F below 20% for coumarin or coumarin-like scaffolds; low dissolution records concern polyhydroxylated flavones, not coumarin.",
      "card_ids": ["C142", "C146"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C97", "C104", "C107", "C109", "C112", "C116", "C129", "C131", "C135", "C144", "C145"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for coumarin itself is present in the supplied records.",
    "L4 records are absorption, solubility, and permeability measurements, not systemic F determinations.",
    "First-pass metabolism of coumarin, such as lactone hydrolysis or 7-hydroxylation, is not directly evidenced and could lower parent F.",
    "Transfer from substituted coumarins to unsubstituted coumarin is qualitative, though structurally close."
  ],
  "decision_summary": "Coumarin is predicted high for F >= 20%. The physicochemical prior is favorable and L4 adds direct coumarin-scaffold absorption evidence: decursin and related coumarins are well absorbed in Caco-2, tromexan and ethylbiscoumacetate are well absorbed in humans, and warfarin shows 94-100% human fraction absorbed. No affirmative F < 20% evidence appears. Confidence stays moderate because no direct coumarin F measurement exists and first-pass metabolism is unquantified."
}

